# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAMİYET\'TE AHLAKİ ERDEMLER (FEZÂİL) VE KAÇINILACAK DAVRANIŞLAR</text>\n  <rect x="25" y="48" width="310" height="188" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Temel Ahlaki Erdemler (Fezâil)</text>\n  <text x="40" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Adalet ve Hakkaniyet:</tspan> Her hak sahibine hakkını verme.</text>\n  <text x="40" y="120" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Sıdk ve Emanet:</tspan> Özde ve sözde doğruluk, güvenilirlik.</text>\n  <text x="40" y="142" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Merhamet ve İhsan:</tspan> Tüm canlılara şefkat ve iyilik.</text>\n  <text x="40" y="164" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">İffet, Hayâ ve Tevazu:</tspan> Öz saygı, edep ve alçakgönüllülük.</text>\n  <rect x="42" y="178" width="276" height="44" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="180" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Nahl Suresi 90. Ayet Özeti:</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10" fill="#334155">\'Şüphesiz Allah adaleti, ihsanı ve yakınlara vermeyi emreder.\'</text>\n\n  <rect x="365" y="48" width="310" height="188" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Yasaklanan Kötü Huylar (Rezâil)</text>\n  <text x="380" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Zulüm ve Kul Hakkı:</tspan> Başkasının canına/malına tecavüz.</text>\n  <text x="380" y="120" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Kizb, Gıybet ve İftira:</tspan> Yalan, arkadan çekiştirme.</text>\n  <text x="380" y="142" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Kibir ve Riya:</tspan> Büyüklenme ve gösteriş yapma.</text>\n  <text x="380" y="164" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Haset ve İsraf:</tspan> Kıskançlık ve nimetleri saçıp savurma.</text>\n  <rect x="382" y="178" width="276" height="44" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.2"/>\n  <text x="520" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Müslüman Tanımı (Hadis-i Şerif):</text>\n  <text x="520" y="212" text-anchor="middle" font-size="10" fill="#334155">\'Elinden ve dilinden insanların emin olduğu kimsedir.\'</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAMİYET\'İN DİĞER DİNLERE VE EHL-İ KİTAP\'A BAKIŞ ÇERÇEVESİ</text>\n  <rect x="20" y="48" width="210" height="182" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Vahyin Köken Birliği</text>\n  <text x="32" y="98" font-size="10.5" fill="#334155">• Hz. Âdem\'den Hz. Muhammed\'e</text>\n  <text x="40" y="113" font-size="10" fill="#475569">tüm peygamberler tevhidi anlatmıştır.</text>\n  <text x="32" y="138" font-size="10.5" fill="#334155">• Müslümanlar Hz. Musa ve Hz. İsa</text>\n  <text x="40" y="153" font-size="10" fill="#475569">dahil tüm nebîlere iman eder.</text>\n  <text x="32" y="178" font-size="10.5" fill="#334155">• Kur\'an-ı Kerim önceki vahiyleri</text>\n  <text x="40" y="193" font-size="10" fill="#475569">tasdik ve tahrifatları tashih eder.</text>\n\n  <rect x="245" y="48" width="210" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. Ehl-i Kitap Statüsü</text>\n  <text x="257" y="98" font-size="10.5" fill="#334155">• Yahudiler ve Hristiyanlar Kur\'an\'da</text>\n  <text x="265" y="113" font-size="10" fill="#475569">\'Ehl-i Kitap\' olarak adlandırılır.</text>\n  <text x="257" y="138" font-size="10.5" fill="#334155">• İnançtaki sapmalar (teslis vb.) tenkit</text>\n  <text x="265" y="153" font-size="10" fill="#475569">edilir ama zorla din dayatılmaz.</text>\n  <text x="257" y="178" font-size="10.5" fill="#334155">• Komşuluk, ticaret ve insani</text>\n  <text x="265" y="193" font-size="10" fill="#475569">yardımlaşma meşru kılınmıştır.</text>\n\n  <rect x="470" y="48" width="210" height="182" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">3. İnanç Hürriyeti İlkesi</text>\n  <text x="482" y="98" font-size="10.5" fill="#334155">• \'Dinde zorlama yoktur\' (Bakara, 256)</text>\n  <text x="490" y="113" font-size="10" fill="#475569">evrensel hukuk kuralıdır.</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">• Başka dinlerin kutsal saydıklarına</text>\n  <text x="490" y="153" font-size="10" fill="#475569">hakaret edilmesi yasaklanmıştır.</text>\n  <text x="482" y="178" font-size="10.5" fill="#334155">• Mabetlerin (havra, kilise) dokunul-</text>\n  <text x="490" y="193" font-size="10" fill="#475569">mazlığı güvence altına alınmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM TARİHİNDE BİRLİKTE YAŞAMA HUKUKUNUN TEMEL BELGELERİ</text>\n  <rect x="20" y="50" width="210" height="175" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="125" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">1. Medine Vesikası (622)</text>\n  <text x="125" y="95" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0c4a6e">&amp; Necran Antlaşması</text>\n  <text x="32" y="120" font-size="10" fill="#334155">• Hz. Peygamber\'in (s.a.v.) Medine\'de</text>\n  <text x="40" y="135" font-size="10" fill="#334155">Yahudilerle imzaladığı vatandaşlık</text>\n  <text x="40" y="150" font-size="10" fill="#334155">ve ortak savunma sözleşmesidir.</text>\n  <text x="32" y="174" font-size="10" fill="#334155">• \'Yahudilerin dini kendilerine,</text>\n  <text x="40" y="189" font-size="10" fill="#334155">Müslümanların dini kendilerinedir.\'</text>\n\n  <rect x="245" y="50" width="210" height="175" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Kudüs Emannamesi (638)</text>\n  <text x="350" y="95" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">(Hz. Ömer Dönemi)</text>\n  <text x="257" y="120" font-size="10" fill="#334155">• Kudüs\'ün fethinde Hristiyan halkın</text>\n  <text x="265" y="135" font-size="10" fill="#334155">canlarına, mallarına, kiliselerine ve</text>\n  <text x="265" y="150" font-size="10" fill="#334155">haçlarına dokunulmayacağı garantisi.</text>\n  <text x="257" y="174" font-size="10" fill="#334155">• Kimsenin dininden dolayı zorlan-</text>\n  <text x="265" y="189" font-size="10" fill="#334155">mayacağının yazılı taahhüdüdür.</text>\n\n  <rect x="470" y="50" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Osmanlı Ahidnameleri</text>\n  <text x="575" y="95" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">&amp; Millet Sistemi (1453-1463)</text>\n  <text x="482" y="120" font-size="10" fill="#334155">• Fatih Sultan Mehmed\'in Galata ve</text>\n  <text x="490" y="135" font-size="10" fill="#334155">Bosna Fransisken Rahiplerine verdiği</text>\n  <text x="490" y="150" font-size="10" fill="#334155">inanç ve ibadet hürriyeti fermanı.</text>\n  <text x="482" y="174" font-size="10" fill="#334155">• Endülüs\'ten kovulan Yahudilere</text>\n  <text x="490" y="189" font-size="10" fill="#334155">Osmanlı topraklarının açılması (1492).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
